14|// Sum of every element. Naive flat loop - touches every byte once, cache
15|// friendly because the data is contiguous.
16|double Matrix::SumAll() const {
17|    double s = 0.0;
18|    for (std::size_t i = 0; i < data_.size(); ++i) {
